/** Every playable stage, in campaign order. */
export const CAMPAIGN: StageDef[] = [
  ...WORLD_ONE,
  ...WORLD_TWO,
  ...WORLD_THREE,
  ...WORLD_FOUR,
  ...WORLD_FIVE,
  ...WORLD_SIX,
  ...WORLD_SEVEN,
  ...WORLD_EIGHT,
]

export function stageWorld(code: string): number {
  return Number(code.split('-')[0])
}

export const SOLID_EMPTY = 0
export const SOLID_GROUND = 1
export const SOLID_BLOCK = 2
export const SOLID_LEDGE = 3
export const SOLID_GATE = 4
export const SOLID_PIPE = 5
export const SOLID_CRATE = 6
export const SOLID_WATER = 7
export const SOLID_BELT_LEFT = 8
export const SOLID_BELT_RIGHT = 9
export const SOLID_BRIDGE = 10

export type SpawnKind =
  | 'token'
  | 'pumpbug'
  | 'rivet-roller'
  | 'steam-vent'
  | 'springstep'
  | 'piston'
  | 'lift'
  | 'checkpoint'
  | 'goal'
  | 'valve'
  | 'boss'
  | 'minnow'
  | 'cork-crab'
  | 'glass-gull'
  | 'moss-lantern'
  | 'spring-hare'
  | 'raft'
  | 'gasket-golem'
  | 'paper-kite'
  | 'umbrella-mite'
  | 'wind'
  | 'cargo'
  | 'puddle-mimic'
  | 'siphon-sprite'
  | 'chimney-spirit'
  | 'tea-kettle-knight'
  | 'power-springstep'
  | 'power-storm'
  | 'power-lift'
  | 'heart'
  | 'gear'
  | 'glider'

export type Spawn = { kind: SpawnKind; col: number; row: number }

export type Door = { col: number; row: number; to: number }

export type Stage = {
  code: string
  name: string
  cols: number
  rows: number
  /** One SOLID_* per tile, row-major. */
  solid: Uint8Array
  start: { col: number; row: number }
  spawns: Spawn[]
  /** Pipe doors: standing on top of one and pressing down leads to `to`. */
  doors: Door[]
  /** The boss gate column, if the stage ends in a boss arena. */
  gate: number | null
  dark: boolean
}

const SPAWNS: Record<string, SpawnKind> = {
  o: 'token',
  p: 'pumpbug',
  r: 'rivet-roller',
  '^': 'steam-vent',
  s: 'springstep',
  P: 'piston',
  L: 'lift',
  K: 'checkpoint',
  G: 'goal',
  v: 'valve',
  M: 'boss',
  m: 'minnow',
  k: 'cork-crab',
  u: 'glass-gull',
  l: 'moss-lantern',
  h: 'spring-hare',
  F: 'raft',
  j: 'gasket-golem',
  y: 'paper-kite',
  n: 'umbrella-mite',
  '~': 'wind',
  Q: 'cargo',
  i: 'puddle-mimic',
  z: 'siphon-sprite',
  t: 'chimney-spirit',
  T: 'tea-kettle-knight',
  '1': 'power-springstep',
  '2': 'power-storm',
  '3': 'power-lift',
  '+': 'heart',
  '*': 'gear',
  '!': 'glider',
}

const SOLIDS: Record<string, number> = {
  '#': SOLID_GROUND,
  B: SOLID_BLOCK,
  '=': SOLID_LEDGE,
  g: SOLID_GATE,
  D: SOLID_PIPE,
  E: SOLID_PIPE,
  c: SOLID_CRATE,
  w: SOLID_WATER,
  '<': SOLID_BELT_LEFT,
  '>': SOLID_BELT_RIGHT,
  ':': SOLID_BRIDGE,
}

/** The top cell of each vertical run of `mark`, left to right. */
function pipeTops(def: StageDef, mark: string) {
  const tops: { col: number; row: number }[] = []
  def.rows.forEach((line, row) => {
    for (let col = 0; col < line.length; col++)
      if (line[col] === mark && def.rows[row - 1]?.[col] !== mark)
        tops.push({ col, row })
  })
  return tops.sort((a, b) => a.col - b.col || a.row - b.row)
}

export function parseStage(def: StageDef): Stage {
  const rows = def.rows.length
  const cols = def.rows[0]!.length
  if (def.rows.some((line) => line.length !== cols))
    throw new Error(`stage ${def.code}: ragged rows`)
  const solid = new Uint8Array(cols * rows)
  const spawns: Spawn[] = []
  let start: { col: number; row: number } | null = null
  let gate: number | null = null
  def.rows.forEach((line, row) => {
    for (let col = 0; col < cols; col++) {
      const ch = line[col]!
      if (SOLIDS[ch]) solid[row * cols + col] = SOLIDS[ch]!
      else if (SPAWNS[ch]) spawns.push({ kind: SPAWNS[ch]!, col, row })
      else if (ch === '@') start = { col, row }
      else if (ch === 'X') gate = col
      else if (ch !== '.') throw new Error(`stage ${def.code}: unknown "${ch}"`)
      if (ch === 'm') solid[row * cols + col] = SOLID_WATER
    }
  })
  if (!start) throw new Error(`stage ${def.code}: no start`)
  const entries = pipeTops(def, 'D')
  const exits = pipeTops(def, 'E')
  if (entries.length !== exits.length)
    throw new Error(`stage ${def.code}: unpaired pipe doors`)
  const doors: Door[] = []
  entries.forEach((entry, i) => {
    doors.push({ ...entry, to: doors.length + 1 })
    doors.push({ ...exits[i]!, to: doors.length - 1 })
  })
  return {
    code: def.code,
    name: def.name,
    cols,
    rows,
    solid,
    start,
    spawns,
    doors,
    gate,
    dark: def.dark === true,
  }
}
